"""No firmware is included. Set V119_OEM_BIN for the optional ARM audit."""
import importlib.util
import os
from pathlib import Path
import struct
import subprocess
import sys
import tempfile
import unittest

SPEC = importlib.util.spec_from_file_location('verify_oem_flow',
    Path(__file__).resolve().parents[1] / 'tools' / 'verify_oem_flow.py')
audit = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(audit)


class CRCReferenceTests(unittest.TestCase):
    def test_original_x6100control_c_vectors(self):
        # Values from compiling the original C, not generated by our function.
        for words, expected in (([], 0xFFFFFFFF), ([0], 0xC704DD7B),
                                ([0x12345678], 0xDF8A8A2B),
                                ([0x04030201, 0x08070605], 0xA3141BDA)):
            with self.subTest(words=words):
                self.assertEqual(audit.crc_words(words), expected)

    def test_independent_full_packet_vector(self):
        data = bytearray((i * 37 + 11) & 255 for i in range(audit.PACKET_SIZE))
        struct.pack_into('<I', data, 0, 0xAA5555AA)
        self.assertEqual(audit.crc_words(struct.unpack('<1033I', data[:0x1024])), 0xE52B5353)


class ImageGuardTests(unittest.TestCase):
    def test_rejects_python_optimization_that_disables_checks(self):
        result = subprocess.run([sys.executable, '-O', str(Path(audit.__file__)),
                                 '--oem-bin', '/nonexistent/stock.bin'],
                                text=True, capture_output=True, check=False)
        self.assertEqual(result.returncode, 2)
        self.assertIn('do not use python -O', result.stderr)

    def test_rejects_wrong_length_before_emulation(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / 'bad.bin'
            path.write_bytes(b'bad')
            with self.assertRaisesRegex(ValueError, 'size'):
                audit.verify(path)

    def test_rejects_wrong_image_even_at_correct_length(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / 'bad.bin'
            path.write_bytes(bytes(audit.OEM_SIZE))
            with self.assertRaisesRegex(ValueError, 'SHA-256'):
                audit.verify(path)

    def test_rejects_directory(self):
        with tempfile.TemporaryDirectory() as directory:
            with self.assertRaisesRegex(ValueError, 'regular file'):
                audit.load_oem(directory)

    def test_rejects_fifo_without_opening(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / 'pipe'
            os.mkfifo(path)
            with self.assertRaisesRegex(ValueError, 'regular file'):
                audit.load_oem(path)


@unittest.skipUnless(os.environ.get('V119_OEM_BIN'), 'set V119_OEM_BIN for OEM ARM integration')
class OEMIntegrationTests(unittest.TestCase):
    def test_exact_stock_packet_producer(self):
        report = audit.verify(Path(os.environ['V119_OEM_BIN']))
        self.assertEqual(len(report['cases']), 3)
        for case in report['cases']:
            self.assertEqual(case['crc_feed_words'], 1033)
            self.assertEqual(case['dma_requested_bytes'], 4136)
            self.assertTrue(case['hkey_setter_updates_word_without_crc'])


if __name__ == '__main__':
    unittest.main()
